<?php require_once 'auth_check.php';require_once '../koneksi.php';require_once 'app_helpers.php';wajib_role(['ADMIN']);$roles=mysqli_query($koneksi,"SELECT id_role,kode_role,nama_role FROM roles ORDER BY nama_role");$prodis=mysqli_query($koneksi,"SELECT ps.id_program_studi,ps.nama_program_studi,f.nama_fakultas FROM program_studi ps JOIN fakultas f ON ps.id_fakultas=f.id_fakultas ORDER BY f.nama_fakultas,ps.nama_program_studi");$faks=mysqli_query($koneksi,"SELECT id_fakultas,nama_fakultas FROM fakultas ORDER BY nama_fakultas");$d=['username'=>'','nama_lengkap'=>'','email'=>'','no_hp'=>'','id_role'=>'','id_fakultas'=>'','id_program_studi'=>'','status_aktif'=>'Aktif'];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();foreach($d as $k=>$v)$d[$k]=trim($_POST[$k]??$v);$d['id_role']=(int)$d['id_role'];$d['id_fakultas']=$d['id_fakultas']!==''?(int)$d['id_fakultas']:null;$d['id_program_studi']=$d['id_program_studi']!==''?(int)$d['id_program_studi']:null;$password=$_POST['password']??'';if(strlen($d['username'])<4||$d['nama_lengkap']===''||$d['id_role']===0||strlen($password)<8)$error='Username minimal 4 karakter, nama, role, dan password minimal 8 karakter wajib diisi.';if(!$error){$hash=password_hash($password,PASSWORD_DEFAULT);$st=mysqli_prepare($koneksi,"INSERT INTO pengguna(id_role,id_universitas,id_fakultas,id_program_studi,username,password_hash,nama_lengkap,email,no_hp,status_aktif) VALUES(?,1,?,?,?,?,?,?,?,?)");mysqli_stmt_bind_param($st,'iiissssss',$d['id_role'],$d['id_fakultas'],$d['id_program_studi'],$d['username'],$hash,$d['nama_lengkap'],$d['email'],$d['no_hp'],$d['status_aktif']);if(mysqli_stmt_execute($st)){audit_log($koneksi,(int)$_SESSION['id_pengguna'],'pengguna',(string)mysqli_insert_id($koneksi),'INSERT',null,$d);flash('success','Pengguna berhasil ditambahkan.');redirect_to('pengguna.php');}$error='Gagal menyimpan: '.mysqli_stmt_error($st);mysqli_stmt_close($st);}}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tambah Pengguna</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><?php include 'topbar.php';include 'sideleftbar.php';?><main class="main-content"><div class="page-heading"><span class="eyebrow">MANAJEMEN PENGGUNA</span><h1>Tambah Pengguna</h1></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="dashboard-panel form-panel"><form method="post"><div class="form-grid"><div class="form-group"><label>Username *</label><input name="username" required value="<?=e($d['username'])?>"></div><div class="form-group"><label>Nama Lengkap *</label><input name="nama_lengkap" required value="<?=e($d['nama_lengkap'])?>"></div><div class="form-group"><label>Password *</label><input type="password" name="password" minlength="8" required></div><div class="form-group"><label>Email</label><input type="email" name="email" value="<?=e($d['email'])?>"></div><div class="form-group"><label>No. HP</label><input name="no_hp" value="<?=e($d['no_hp'])?>"></div><div class="form-group"><label>Role *</label><select name="id_role" required><option value="">Pilih role</option><?php while($x=mysqli_fetch_assoc($roles)):?><option value="<?=$x['id_role']?>" <?=$d['id_role']==$x['id_role']?'selected':''?>><?=e($x['nama_role'])?> (<?=e($x['kode_role'])?>)</option><?php endwhile;?></select></div><div class="form-group"><label>Fakultas</label><select name="id_fakultas"><option value="">-</option><?php while($x=mysqli_fetch_assoc($faks)):?><option value="<?=$x['id_fakultas']?>" <?=$d['id_fakultas']==$x['id_fakultas']?'selected':''?>><?=e($x['nama_fakultas'])?></option><?php endwhile;?></select></div><div class="form-group"><label>Program Studi</label><select name="id_program_studi"><option value="">-</option><?php while($x=mysqli_fetch_assoc($prodis)):?><option value="<?=$x['id_program_studi']?>" <?=$d['id_program_studi']==$x['id_program_studi']?'selected':''?>><?=e($x['nama_fakultas'].' - '.$x['nama_program_studi'])?></option><?php endwhile;?></select></div><div class="form-group"><label>Status</label><select name="status_aktif"><option>Aktif</option><option>Tidak Aktif</option></select></div></div><div class="form-actions"><a class="btn btn-outline" href="pengguna.php">Batal</a><button class="btn btn-primary">Simpan</button></div><?=csrf_field()?></form></div></main><script src="script.js"></script></body></html>